export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export type QuoteResult = { premium: number };
export type ClaimResult = { payout: number; remainingCap: number };
export type Result = QuoteResult | ClaimResult;

interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEM_PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function priceListEntry(item: Item): PriceListEntry {
  return isComponent(item) ? COMPONENT_PRICE : MAIN_ITEM_PRICE_LIST[item.type];
}

const PROCESSING_FEE = 5;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

function alikeComponentsBasePremium(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_PRICE.basePremium;
}

function componentsBasePremium(items: Item[]): number {
  return COMPONENT_TYPES.reduce(
    (sum, type) => sum + alikeComponentsBasePremium(items.filter((item) => item.type === type).length),
    0,
  );
}

function mainItems(items: Item[]): Item[] {
  return items.filter((item) => !isComponent(item));
}

function mainItemBasePremium(item: Item): number {
  return priceListEntry(item).basePremium;
}

function mainItemsBasePremium(items: Item[]): number {
  return mainItems(items).reduce((sum, item) => sum + mainItemBasePremium(item), 0);
}

function enchantmentLevel(item: Item): number {
  return item.enchantment ?? 0;
}

function isHighlyEnchanted(item: Item): boolean {
  return enchantmentLevel(item) >= HIGH_ENCHANTMENT_LEVEL;
}

function itemRiskSurchargeRate(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE_RATE : 0;
  const highEnchantment = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0;
  return curse + highEnchantment;
}

function itemRiskSurcharges(items: Item[]): number {
  return mainItems(items).reduce((sum, item) => sum + mainItemBasePremium(item) * itemRiskSurchargeRate(item), 0);
}

function policyBasePremium(items: Item[]): number {
  return mainItemsBasePremium(items) + componentsBasePremium(items);
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
}

function policyModifierRate(customer: Customer, isFollowUpContract: boolean): number {
  const loyalty = isLongStandingCustomer(customer) ? -LOYALTY_DISCOUNT_RATE : 0;
  const followUpContract = isFollowUpContract ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
  return FIRST_INSURANCE_SURCHARGE_RATE + loyalty + followUpContract;
}

function quotePremium(customer: Customer, isFollowUpContract: boolean, items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const policyModifiers = basePremium * policyModifierRate(customer, isFollowUpContract);
  return Math.ceil(basePremium + itemRiskSurcharges(items) + policyModifiers + PROCESSING_FEE);
}

function isFollowUpContract(earlierSteps: Scenario["steps"]): boolean {
  return earlierSteps.some((step) => step.op === "quote");
}

const CAP_MULTIPLIER = 2;
const DEDUCTIBLE = 100;
const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
const FULL_REIMBURSEMENT_RATE = 1;
const REDUCED_REIMBURSEMENT_RATE = 0.5;

function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceListEntry(item).insuranceValue, 0);
}

function payoutCap(items: Item[]): number {
  return insuranceSum(items) * CAP_MULTIPLIER;
}

function reimbursementRate(item: Item): number {
  return enchantmentLevel(item) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL ? REDUCED_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
}

function damagePayout(insuredItems: Item[], damage: Damage): number {
  const damagedItem = insuredItems.find((item) => item.type === damage.itemType) as Item;
  return damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE;
}

function claimPayout(insuredItems: Item[], damages: Damage[]): number {
  return Math.floor(damages.reduce((sum, damage) => sum + damagePayout(insuredItems, damage), 0));
}

function settleClaim(remainingCap: number, insuredItems: Item[], damages: Damage[]): ClaimResult {
  const payout = Math.min(claimPayout(insuredItems, damages), remainingCap);
  return { payout, remainingCap: remainingCap - payout };
}

function processClaim(steps: Scenario["steps"], remainingCaps: Map<number, number>, claim: ClaimStep): Result {
  const policy = steps[claim.policy] as QuoteStep;
  const remainingCap = remainingCaps.get(claim.policy) ?? payoutCap(policy.items);
  const result = settleClaim(remainingCap, policy.items, claim.incident.damages);
  remainingCaps.set(claim.policy, result.remainingCap);
  return result;
}

export function runScenario(scenario: Scenario): Result[] {
  const remainingCaps = new Map<number, number>();
  return scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      return processClaim(scenario.steps, remainingCaps, step);
    }
    const followUpContract = isFollowUpContract(scenario.steps.slice(0, index));
    return { premium: quotePremium(scenario.customer, followUpContract, step.items) };
  });
}
